import os,pathlib,json,base64,hashlib,tempfile,subprocess,datetime,sys
FILES={'operator-support.py': {'sha256': 'f0fcfb7b6286bf01e0ce40d0a02d960e171c3459947b2d771d976685a6dee4af', 'data': ''}, 'unit-profile.json': {'sha256': '4bcbf42abefa3cba29114d49c7601a0186ca0df25cf1c51ba72d87a2dfa12b72', 'data': ''}}
SQL="BEGIN READ ONLY;\nSET LOCAL statement_timeout='5s';SET LOCAL lock_timeout='2s';\nDO $$ BEGIN\nIF current_database()<>'stockinsider' OR current_user<>'postgres' OR current_setting('data_directory')<>'/var/lib/postgresql/17/stockinsider' THEN RAISE EXCEPTION 'database_identity_mismatch'; END IF;\nIF (SELECT count(*) FROM public.production_writer_releases WHERE active)<>1 OR EXISTS(SELECT FROM public.production_writer_releases WHERE active AND (release_id IS DISTINCT FROM '169aad1b6cfa747f78ae3464b614f43c0749d806' OR writer_kind IS DISTINCT FROM 'vps')) THEN RAISE EXCEPTION 'active_writer_identity_mismatch'; END IF;\nIF EXISTS(SELECT FROM public.production_write_leases WHERE lease_key='production-data-plane') THEN RAISE EXCEPTION 'deployment_requires_empty_data_plane_lease'; END IF;\nEND $$;\nSELECT json_build_object('observedAt',clock_timestamp(),'serverVersionNum',current_setting('server_version_num'),'activeWriterCount',(SELECT count(*) FROM public.production_writer_releases WHERE active),'releaseId','169aad1b6cfa747f78ae3464b614f43c0749d806','dataPlaneLeaseRows',(SELECT count(*) FROM public.production_write_leases WHERE lease_key='production-data-plane'));\nROLLBACK;\n"

assert os.geteuid()==0
OLD='/opt/stockinsider-standalone/releases/169aad1b6cfa747f78ae3464b614f43c0749d806'
assert os.path.realpath('/opt/stockinsider/current')==OLD
assert not os.path.lexists('/opt/stockinsider-standalone/releases/dd59817f750684b093965f539dd4de466be13077')
leaf=pathlib.Path(tempfile.mkdtemp(prefix='stockinsider-dd-pr382-profile.',dir='/run'))
completed=False
try:
 for name,row in FILES.items():
  b=base64.b64decode(row['data']);assert hashlib.sha256(b).hexdigest()==row['sha256']
  fd=os.open(leaf/name,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
  with os.fdopen(fd,'wb') as f:f.write(b);f.flush();os.fsync(f.fileno())
  assert hashlib.sha256((leaf/name).read_bytes()).hexdigest()==row['sha256']
 r=subprocess.run(['/usr/bin/python3','-I',str(leaf/'operator-support.py'),'profile',OLD.rsplit('/',1)[1]],capture_output=True,text=True,timeout=25)
 print('PROFILE_STDOUT='+r.stdout.strip());print('PROFILE_EXIT='+str(r.returncode));assert r.returncode==0,r.stderr
 q=subprocess.run(['/usr/sbin/runuser','-u','postgres','--','/usr/bin/env','-i','PATH=/usr/bin:/bin','PGCONNECT_TIMEOUT=5','/usr/bin/psql','-h','/var/run/postgresql','-p','5432','-U','postgres','-d','stockinsider','-X','-w','-A','-t','-v','ON_ERROR_STOP=1'],input=SQL,capture_output=True,text=True,timeout=20)
 print('WRITER_STDOUT='+q.stdout.strip());print('WRITER_EXIT='+str(q.returncode));assert q.returncode==0,q.stderr
 mem=dict((x.split(':',1)[0],x.split(':',1)[1].strip()) for x in pathlib.Path('/proc/meminfo').read_text().splitlines())
 avail=int(mem['MemAvailable'].split()[0])*1024
 print('PREFLIGHT='+json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'current':os.path.realpath('/opt/stockinsider/current'),'memoryAvailableBytes':avail,'requiredBytes':2684354560,'memoryEnough':avail>=2684354560,'originalThreeLocksHeld':True,'exactMergedProfilePassed':True,'writerReadOnlyPassed':True,'heavyCapacityRun':False,'activationExecuted':False,'deploy':False,'temporaryStagingOnly':True}))
 completed=True
finally:
 for name in FILES:
  f=leaf/name
  if os.path.lexists(f):f.unlink()
 leaf.rmdir()
 print('OWNED_PROFILE_STAGE_CLEANUP_CONFIRMED='+str(not leaf.exists()))
assert completed
